<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import CustomFieldSelector from './CustomFieldSelector.vue'
import VariableInsert from './VariableInsert.vue'
const props=defineProps({draft:{type:Object,required:true},fields:{type:Array,default:()=>[]},inputVariables:{type:Array,default:()=>[]}})
const emit=defineEmits(['field-created'])
const validationTextarea=ref(null)
const textTypes=new Set(['text','email','phone','date','number','integer','decimal']),lengthTypes=new Set(['text','email','phone']),numberTypes=new Set(['number','integer','decimal'])
const isText=computed(()=>textTypes.has(props.draft.reply_type)),hasLength=computed(()=>lengthTypes.has(props.draft.reply_type)),isNumber=computed(()=>numberTypes.has(props.draft.reply_type)),isDate=computed(()=>props.draft.reply_type==='date'),isMedia=computed(()=>['image','audio','video','document','sticker','media'].includes(props.draft.reply_type)),isImage=computed(()=>props.draft.reply_type==='image'),isTelegramPhone=computed(()=>props.draft.reply_type==='telegram_phone'),isChoice=computed(()=>['choice','multiple_choice'].includes(props.draft.reply_type))
const answerKey=computed({
  get(){return String(props.draft.answer_key||props.draft.title||'').replace(/^Question$/i,'')},
  set(value){const key=String(value||'').toLowerCase().trim().replace(/[^a-z0-9_.-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,120);props.draft.answer_key=key;if(!props.draft.answer_key_persisted)props.draft.title=key||'Question'}
})
const answerVariable=computed(()=>answerKey.value?`%input.${answerKey.value}%`:'Set a key to create a reusable variable')
function suggestFieldKey(id){if(answerKey.value||!id)return;const field=props.fields.find(item=>String(item.id)===String(id));if(field?.key)answerKey.value=field.key}
watch(()=>props.draft.capture_field_id,suggestFieldKey,{immediate:true})
watch(()=>props.fields,()=>suggestFieldKey(props.draft.capture_field_id),{deep:true})
function readChoices(){try{const rows=JSON.parse(props.draft.pattern||'[]');return Array.isArray(rows)?rows.map(x=>typeof x==='string'?{label:x,value:x}:{label:String(x?.label||''),value:String(x?.value??x?.label??'')}):[]}catch{return []}}
const choices=computed(()=>readChoices())
function writeChoices(rows){props.draft.pattern=JSON.stringify(rows.map(x=>({label:String(x.label||'').slice(0,80),value:String(x.value||x.label||'').slice(0,200)})))}
function addChoice(){const rows=readChoices();rows.push({label:'',value:''});writeChoices(rows)}
function removeChoice(index){const rows=readChoices();rows.splice(index,1);writeChoices(rows)}
function updateChoice(index,key,value){const rows=readChoices();if(!rows[index])return;rows[index][key]=value;if(key==='label'&&!rows[index].value)rows[index].value=value;writeChoices(rows)}
watch(()=>props.draft.reply_type,(next,previous)=>{if(['choice','multiple_choice'].includes(next)){let rows=readChoices();if(!rows.length)writeChoices([{label:'Yes',value:'Yes'},{label:'No',value:'No'}])}else if(['choice','multiple_choice'].includes(previous)){props.draft.pattern=''}})
async function insertValidationVariable(token){const el=validationTextarea.value,value=props.draft.validation_error||'',start=el?.selectionStart??value.length,end=el?.selectionEnd??start;props.draft.validation_error=value.slice(0,start)+token+value.slice(end);await nextTick();if(el){const pos=start+token.length;el.focus();el.setSelectionRange(pos,pos)}}
</script>
<template><section class="question-editor"><div class="section-title"><b>Reply & validation</b><small>Control what the contact may send before the flow continues.</small></div><label class="answer-key">Answer key / variable name<input v-model="answerKey" placeholder="e.g. name or product"><small class="help">Use a short stable key. This answer becomes available to later blocks as <code>{{answerVariable}}</code>. If you choose a custom field below, its key is suggested automatically when this is blank.</small></label><label>Expected reply type<select v-model="draft.reply_type"><optgroup label="Choice"><option value="choice">Multiple choice</option></optgroup><optgroup label="Text & data"><option value="text">Text</option><option value="email">Email address</option><option value="phone">Phone number (typed)</option><option value="telegram_phone">Telegram — Share phone number</option><option value="date">Date</option><option value="number">Number</option><option value="integer">Whole number</option><option value="decimal">Decimal number</option></optgroup><optgroup label="Media"><option value="image">Photo / image</option><option value="audio">Audio / voice note</option><option value="video">Video</option><option value="document">Document / file</option><option value="sticker">Sticker</option><option value="media">Any media</option></optgroup></select><small class="help choice-help" v-if="isChoice">The subscriber sees clickable choices. The selected value is stored exactly like any other Question answer and is available to custom fields, User Input variables, conditions and webhooks.</small><small class="help" v-else-if="isImage">Image replies are copied into WA Connect storage and the durable image URL becomes the answer value.</small><small class="help" v-else-if="isMedia">The flow remains waiting until the contact sends the selected media type. “Any media” accepts a photo, video, audio/voice note, document or sticker.</small><small class="help telegram-help" v-if="isTelegramPhone">Telegram shows a native <b>Share phone number</b> button. The supplied number is automatically stored in the system Subscriber ID field and the flow continues after Telegram returns the contact.</small></label><div v-if="isChoice" class="choice-editor"><div class="choice-head"><div><b>Answer choices</b><small>Label is shown to the subscriber. Value is what Buccaneer stores.</small></div><button type="button" @click="addChoice">+ Add choice</button></div><div v-for="(choice,index) in choices" :key="index" class="choice-row"><span>{{index+1}}</span><input :value="choice.label" maxlength="80" placeholder="Label, e.g. Yes" @input="updateChoice(index,'label',$event.target.value)"><input :value="choice.value" maxlength="200" placeholder="Stored value" @input="updateChoice(index,'value',$event.target.value)"><button type="button" title="Remove choice" @click="removeChoice(index)">×</button></div><small class="help">WhatsApp displays up to 3 reply buttons; Telegram supports up to 10. For cross-channel flows, keep questions to 3 choices.</small></div><label class="check"><input v-model="draft.required" type="checkbox"><span><b>Reply required</b><small>When disabled, a blank text/data answer is allowed and the flow may continue with an empty value.</small></span></label><label v-if="!isTelegramPhone">Save valid reply to<CustomFieldSelector v-model="draft.capture_field_id" :fields="fields" value-mode="id" empty-label="Do not save reply" @field-created="emit('field-created',$event)"/><small class="help" v-if="isImage">For an Image URL custom field, WA Connect stores the durable URL rather than Telegram/WhatsApp media metadata.</small><small class="help" v-else-if="isMedia">Media replies store stable channel metadata so the original media can be identified and reused later.</small><small class="help" v-else>Optional. Saving to a custom field makes the value persistent on the subscriber as well as available through the User Input submission.</small></label><div v-else class="native-button-preview"><span>Telegram button</span><b>📱 Share phone number</b><small>Subscriber ID is populated automatically; no custom field is required.</small></div><div v-if="hasLength" class="two"><label>Minimum length<input v-model="draft.min_length" type="number" min="0" placeholder="None"></label><label>Maximum length<input v-model="draft.max_length" type="number" min="1" placeholder="None"></label></div><div v-if="isNumber" class="two"><label>Minimum value<input v-model="draft.min_value" type="number" placeholder="None"></label><label>Maximum value<input v-model="draft.max_value" type="number" placeholder="None"></label></div><label v-if="isDate">Date format<input v-model="draft.date_format" placeholder="%Y-%m-%d"><small class="help">Default is YYYY-MM-DD.</small></label><label v-if="isText">Validation pattern <span class="optional">optional</span><input v-model="draft.pattern" placeholder="Regular expression"><small class="help">Advanced: require the entire text reply to match a regular expression.</small></label><label>Invalid reply message<textarea ref="validationTextarea" v-model="draft.validation_error" rows="3" placeholder="Leave blank to use the automatic message"></textarea><VariableInsert :fields="fields" :input-variables="inputVariables" @insert="insertValidationVariable"/><small class="help">Sent when the reply has the wrong type or fails validation. The flow stays on this Question block.</small></label></section></template>
<style scoped>.question-editor{margin-top:20px;padding-top:18px;border-top:1px solid #e5ece9}.section-title{margin-bottom:15px}.section-title b,.section-title small{display:block}.section-title small,.help{margin-top:4px;color:#7c8b85;font-weight:400;line-height:1.4}.answer-key{padding:12px;border:1px solid #cfe3d9;border-radius:9px;background:#f5fbf7}.answer-key code{color:#168653;font-weight:700}.telegram-help,.choice-help{padding:9px 10px;background:#eef8fd;border:1px solid #d2edf9;border-radius:7px;color:#39758e}.native-button-preview{margin:0 0 14px;padding:11px 12px;border:1px solid #d2edf9;border-radius:8px;background:#f7fcfe}.native-button-preview span,.native-button-preview b,.native-button-preview small{display:block}.native-button-preview span{font-size:11px;text-transform:uppercase;color:#6990a0;font-weight:700}.native-button-preview b{margin-top:6px;color:#229ed9}.native-button-preview small{margin-top:5px;color:#7c8b85}.choice-editor{margin:0 0 14px;padding:12px;border:1px solid #d7e4de;border-radius:9px;background:#fbfdfc}.choice-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}.choice-head b,.choice-head small{display:block}.choice-head small{margin-top:3px;color:#7c8b85}.choice-head button{border:1px solid #b9dcc9;background:#eef9f3;color:#12814c;border-radius:7px;padding:7px 9px;font-weight:700;white-space:nowrap}.choice-row{display:grid;grid-template-columns:24px minmax(0,1fr) minmax(0,1fr) 30px;gap:7px;align-items:center;margin-bottom:7px}.choice-row>span{font-size:11px;color:#84938c;text-align:center}.choice-row input{margin:0!important}.choice-row button{border:0;background:transparent;color:#a05252;font-size:20px;cursor:pointer}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{flex-direction:row!important;align-items:flex-start;gap:10px!important;padding:11px 12px;border:1px solid #e0e8e4;border-radius:8px}.check input{width:auto!important;margin-top:2px}.check span,.check b,.check small{display:block}.check small{margin-top:3px;color:#7c8b85;font-weight:400}.optional{font-weight:400;color:#8b9a94}.question-editor label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin-bottom:14px}.question-editor input,.question-editor textarea,.question-editor select{border:1px solid #d7e1dd;border-radius:8px;padding:10px;font:inherit;background:#fff}</style>